const allInputs = $input.all();
let items = [];

for (const input of allInputs) {
  const json = input.json;
  if (Array.isArray(json.body)) {
    items = items.concat(json.body);
  } else if (json.body && typeof json.body === 'object') {
    items.push(json.body);
  } else if (Array.isArray(json)) {
    items = items.concat(json);
  } else if (json && json.sku) {
    items.push(json);
  }
}

// Safety check: Prevent destructive execution if zero records received
if (items.length === 0) {
  return [{
    json: {
      is_valid_scrape: false,
      error_message: 'Empty scrape detected (0 records). Safeguard tripped to protect dataset.',
      records: []
    }
  }];
}

return [{
  json: {
    is_valid_scrape: true,
    total_raw_count: items.length,
    raw_records: items
  }
}];

const rawData = $('Ingest & Check Volume').first().json.raw_records || [];
const nowIso = new Date().toISOString();

const ratingMap = {
  'one': 1,
  'two': 2,
  'three': 3,
  'four': 4,
  'five': 5
};

const cleanedRecords = [];

for (const raw of rawData) {
  const sku = (raw.sku || '').trim();
  const title = (raw.title_raw || raw.title || '').trim();
  if (!sku || !title) continue;

  // Clean Price: remove any non-digit/dot characters
  const rawPriceStr = String(raw.price_raw || raw.price || '0');
  const priceClean = parseFloat(rawPriceStr.replace(/[^0-9.]/g, '')) || 0.0;

  // Normalize Rating
  const ratingKey = String(raw.rating_raw || raw.rating || '').toLowerCase().trim();
  const ratingClean = ratingMap[ratingKey] || 0;

  // Normalize Availability
  const availStr = String(raw.availability_raw || raw.availability || '').toLowerCase();
  const inStock = availStr.includes('in stock') || raw.in_stock === true;

  cleanedRecords.push({
    record_id: sku,
    source: raw.source || 'books.toscrape.com',
    title: title,
    category: (raw.category_raw || raw.category || 'Books').trim(),
    price: priceClean,
    currency: 'GBP',
    rating: ratingClean,
    in_stock: inStock,
    product_url: raw.product_url || '',
    image_url: raw.image_url || '',
    status: 'active',
    scraped_at: raw.scraped_at || nowIso
  });
}

return [{
  json: {
    cleaned_records: cleanedRecords
  }
}];

const cleaned = $('Clean & Normalize Records').first().json.cleaned_records || [];
const existingRows = $input.all().map(i => i.json).filter(r => r && r.record_id);

const existingMap = new Map();
for (const row of existingRows) {
  existingMap.set(row.record_id, row);
}

const nowIso = new Date().toISOString();
const newRecords = [];
const updatedRecords = [];
const unchangedRecords = [];

for (const item of cleaned) {
  const existing = existingMap.get(item.record_id);

  if (!existing) {
    // Brand new record
    newRecords.push({
      ...item,
      first_seen_at: nowIso,
      last_seen_at: nowIso,
      last_changed_at: nowIso,
      diff_status: 'NEW'
    });
  } else {
    // Existing record - detect attribute differences
    const priceChanged = Math.abs((existing.price || 0) - item.price) > 0.001;
    const stockChanged = (existing.in_stock !== item.in_stock);
    const titleChanged = (existing.title !== item.title);

    if (priceChanged || stockChanged || titleChanged) {
      updatedRecords.push({
        ...item,
        first_seen_at: existing.first_seen_at || nowIso,
        last_seen_at: nowIso,
        last_changed_at: nowIso,
        status: 'updated',
        diff_status: 'UPDATED'
      });
    } else {
      unchangedRecords.push({
        ...item,
        first_seen_at: existing.first_seen_at || nowIso,
        last_seen_at: nowIso,
        last_changed_at: existing.last_changed_at || nowIso,
        status: 'active',
        diff_status: 'UNCHANGED'
      });
    }
  }
}

return [{
  json: {
    total_processed: cleaned.length,
    new_count: newRecords.length,
    updated_count: updatedRecords.length,
    unchanged_count: unchangedRecords.length,
    new_records: newRecords,
    updated_records: updatedRecords,
    unchanged_records: unchangedRecords
  }
}];

const diff = $('Deduplicate & Detect Changes').first().json;
const toInsert = diff.new_records || [];

if (toInsert.length === 0) {
  return [{ json: { has_new_records: false } }];
}

return toInsert.map(r => ({
  json: {
    has_new_records: true,
    record_id: r.record_id,
    source: r.source,
    title: r.title,
    category: r.category,
    price: r.price,
    currency: r.currency,
    rating: r.rating,
    in_stock: r.in_stock,
    product_url: r.product_url,
    image_url: r.image_url,
    status: r.status,
    first_seen_at: r.first_seen_at,
    last_seen_at: r.last_seen_at,
    last_changed_at: r.last_changed_at,
    scraped_at: r.scraped_at
  }
}));
